let attentionBoard=null,attentionSequence=0;
const attentionKindNames={report:'Offene Meldebewertungen',block:'Aktive Sperren',overdue:'Überfällige Kontrollen',due:'Anstehende Kontrollen',unknown:'Ungeklärte Kontrollpflichten',not_commissioned:'Fehlende Inbetriebnahmenachweise'};
function renderDeviceAttention(){
 const list=document.querySelector('#attention-list');list.replaceChildren();if(!attentionBoard)return;
 const kind=document.querySelector('#attention-filter').value;
 for(const item of attentionBoard.devices){const reasons=item.reasons.filter(reason=>kind==='all'||reason.kind===kind);if(!reasons.length)continue;
 const entry=document.createElement('li'),heading=document.createElement('strong');heading.textContent=`${item.inventory_number} · ${item.name} · ${locations.find(location=>location.id===item.location_id)?.name||'Lagerort'} · Version ${item.version}`;entry.append(heading);
 for(const reason of reasons){const p=document.createElement('p');p.textContent=`${attentionKindNames[reason.kind]}${reason.control_type?' · '+(reason.control_type==='electrical'?'Elektrische Kontrolle':reason.control_type):''}${reason.due_on?' · '+reason.due_on:''}${reason.days_remaining!==undefined?' · '+(reason.days_remaining<0?Math.abs(reason.days_remaining)+' Tage überfällig':reason.days_remaining===0?'Heute fällig':'In '+reason.days_remaining+' Tagen'):''}${reason.source_version?' · Bezug auf Version '+reason.source_version:''} · ${reason.description}`;entry.append(p);}
 const link=document.createElement('a');link.href=`/api/v1/devices/${encodeURIComponent(item.id)}/export.zip`;link.textContent='Geräteakte mit Nachweisen herunterladen';entry.append(link);list.append(entry);
 }
 if(!list.children.length){const entry=document.createElement('li');entry.textContent='Keine Hinweise für diesen Filter.';list.append(entry);}
}
async function loadDeviceAttention(){
 const owner=user?.id;if(!owner)return;const sequence=++attentionSequence,days=document.querySelector('#attention-days').value;
 attentionBoard=null;document.querySelector('#reminder-mail-list').replaceChildren();document.querySelector('#reminder-mail-status').textContent='';document.querySelector('#reminder-list').replaceChildren();document.querySelector('#reminder-status').textContent='';document.querySelector('#attention-list').replaceChildren();document.querySelector('#attention-counts').textContent='';const message=document.querySelector('#attention-status');message.textContent='Arbeitsübersicht wird geladen …';
 try{const response=await fetch('/api/v1/devices/attention?days='+encodeURIComponent(days),{cache:'no-store'});if(user?.id!==owner||sequence!==attentionSequence)return;if(response.status===401){signedOut('Bitte erneut anmelden.');return;}const result=await response.json();if(user?.id!==owner||sequence!==attentionSequence)return;if(!response.ok)throw new Error(result.message||'Arbeitsübersicht nicht verfügbar.');attentionBoard=result;
 message.textContent=`Datenstand ${result.as_of} · Fachlicher Tag ${result.day} · ${result.devices.length} Geräte mit Hinweisen von ${result.scanned_devices} Geräten · Zeitraum ${result.horizon_days} Tage. Zähler beziehen sich auf einzelne Hinweise.`;
 document.querySelector('#attention-counts').textContent=Object.entries(attentionKindNames).map(([kind,label])=>`${label}: ${result.counts[kind]||0}`).join(' · ');renderDeviceAttention();await loadDeviceReminders(owner,sequence);if(user?.id===owner&&sequence===attentionSequence)await loadReminderMailStatus(owner,sequence);
 }catch(error){if(user?.id===owner&&sequence===attentionSequence)message.textContent=error.message;}
}
document.querySelector('#attention-refresh').addEventListener('click',loadDeviceAttention);
document.querySelector('#attention-days').addEventListener('change',loadDeviceAttention);
document.querySelector('#attention-filter').addEventListener('change',renderDeviceAttention);

async function loadDeviceReminders(owner,sequence){
 const message=document.querySelector('#reminder-status'),list=document.querySelector('#reminder-list');
 try{
  const response=await fetch('/api/v1/devices/reminders',{cache:'no-store'});if(user?.id!==owner||sequence!==attentionSequence)return;
  if(response.status===401){signedOut('Bitte erneut anmelden.');return;}
  const result=await response.json();if(user?.id!==owner||sequence!==attentionSequence)return;
  if(!response.ok)throw new Error(result.message||'Erinnerungen nicht verfügbar.');
  const stale=result.last_worker_success && Date.parse(result.as_of)-Date.parse(result.last_worker_success)>2*60*60*1000;
  message.textContent=result.last_worker_success?`Letzter erfolgreicher Hintergrundlauf: ${result.last_worker_success} · Schwellen: ${result.thresholds.join(', ')} Tage sowie heute/überfällig.${stale?' Hintergrundlauf seit über zwei Stunden nicht bestätigt; aktuelle Arbeitsübersicht prüfen.':''}`:'Noch kein erfolgreicher Hintergrundlauf. Aktuelle Arbeitsübersicht prüfen.';
  list.replaceChildren();
  for(const item of result.reminders){const entry=document.createElement('li');entry.textContent=`${item.inventory_number} · ${item.name} · ${item.control_type==='electrical'?'Elektrische Kontrolle':item.control_type} · Fällig ${item.due_on} · ${item.days_remaining<0?Math.abs(item.days_remaining)+' Tage überfällig':item.days_remaining===0?'Heute fällig':'In '+item.days_remaining+' Tagen'} · Erzeugt ${item.created_at} bei ${item.threshold_days===-1?'Überschreitung':item.threshold_days===0?'Fälligkeit':item.threshold_days+'-Tage-Schwelle'} · Geräteversion ${item.source_version}`;list.append(entry);}
  if(!result.reminders.length){const entry=document.createElement('li');entry.textContent='Keine gespeicherten Erinnerungen für aktuell gültige Kontrollfristen in Ihrem Bereich.';list.append(entry);}
 }catch(error){if(user?.id===owner&&sequence===attentionSequence){list.replaceChildren();message.textContent=error.message;}}
}

async function loadReminderMailStatus(owner,sequence){
 const message=document.querySelector('#reminder-mail-status'),list=document.querySelector('#reminder-mail-list');
 try{
  const response=await fetch('/api/v1/devices/reminder-mail',{cache:'no-store'});if(user?.id!==owner||sequence!==attentionSequence)return;
  if(response.status===401){signedOut('Bitte erneut anmelden.');return;}
  const result=await response.json();if(user?.id!==owner||sequence!==attentionSequence)return;
  if(!response.ok)throw new Error(result.message||'Versandstatus nicht verfügbar.');
  const labels={pending:'Wartend',sending:'In Übertragung',retry:'Wiederholung geplant',accepted:'Vom SMTP-Server angenommen',failed:'Fehlgeschlagen',uncertain:'Annahme unklar – manuell prüfen',skipped:'Nicht gesendet (überholt oder Empfänger entfernt)'};
  message.textContent=result.length?`${result.length} protokollierte Zustellungen im Bereich.${response.headers.get('X-Has-More')==='true'?' Anzeige auf die letzten 200 begrenzt; weitere Einträge vorhanden.':''}`:'Noch kein Versand protokolliert. SMTP wird nur über ausdrückliche Konfiguration aktiviert.';
  list.replaceChildren();for(const item of result){const entry=document.createElement('li');entry.textContent=`${item.inventory_number} · ${item.name} · ${item.control_type} · Fällig ${item.due_on} · ${labels[item.state]||item.state} · Versuche ${item.attempts} · Letzter Versuch ${item.last_attempt_at||'noch keiner'}${item.state==='retry'?' · Nächster Versuch '+item.next_attempt_at:''} · Zustellungs-ID ${item.id} · Message-ID ${item.message_id}`;list.append(entry);}
 }catch(error){if(user?.id===owner&&sequence===attentionSequence){list.replaceChildren();message.textContent=error.message;}}
}

