recallCreateForm.addEventListener('submit',async event=>{event.preventDefault();if(!user||recallPending||recallDraft)return;const owner=user.id,sequence=++recallSequence,kind=document.querySelector('#recall-kind').value;if(!recallCanCoordinate(kind))return;const selector={kind};if(kind==='material'){selector.product_id=document.querySelector('#recall-product').value;selector.batch_id=document.querySelector('#recall-batch').value;}else for(const key of ['manufacturer','model','serial_exact','serial_from','serial_to'])selector[key]=document.querySelector('#recall-'+key.replaceAll('_','-')).value;const body={action:'create',selector,title:document.querySelector('#recall-title').value,reference:document.querySelector('#recall-reference').value,evidence:document.querySelector('#recall-source').value,note:document.querySelector('#recall-create-note').value};const frozen=JSON.stringify(body);for(const input of recallCreateForm.elements)input.disabled=true;try{const response=await fetch('/api/v1/recalls/preview',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:frozen});const result=await response.json();if(sequence!==recallSequence||user?.id!==owner)return;if(response.status===401){signedOut('Bitte erneut anmelden.');return;}if(!response.ok)throw Error(result.message||'Vorschau fehlgeschlagen.');recallDraft={owner,body:{...body,preview_basis:result.basis_hash}};const list=document.querySelector('#recall-preview-list');list.replaceChildren();for(const t of result.targets){const p=document.createElement('p');p.textContent=t.name+' · '+t.identity+' · '+t.location+' · '+t.quantity;list.append(p);}document.querySelector('#recall-status').textContent=result.targets.length+' Treffer geprüft. Aktivierung sperrt auch spätere passende Eingänge.';}catch(error){if(sequence===recallSequence&&user?.id===owner)document.querySelector('#recall-status').textContent=error.message;}finally{if(user?.id===owner){recallCreateChoices();recallLock();}}});
async function recallSend(){if(!recallPending||recallPending.owner!==user?.id)return;const request=recallPending,owner=user.id;recallLock();document.querySelector(request.mode==='create'?'#recall-create':'#recall-action-submit').disabled=true;try{const response=await fetch('/api/v1/recalls',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf,'Idempotency-Key':request.key},body:request.body});const result=await response.json();if(user?.id!==owner||recallPending!==request)return;if(response.status===401){signedOut('Erneut mit demselben Konto anmelden und Vorgang wiederholen.');return;}if(!response.ok){if(response.status<500){recallPending=null;recallDraft=null;recallCreateChoices();recallLock();document.querySelector('#recall-status').textContent=(result.message||'Vorgang abgelehnt.')+' Neu laden und abgleichen.';return;}throw Error('uncertain');}recallPending=null;recallDraft=null;for(const id of ['recall-note','recall-evidence','recall-create-note'])document.querySelector('#'+id).value='';await loadRecalls();if(user?.id===owner){document.querySelector('#recall-select').value=result.id;recallRender();document.querySelector('#recall-status').textContent='Rückrufvorgang gespeichert. Version '+result.version+'.';await loadStock();if(user)await loadDevices();}}catch{if(user?.id===owner&&recallPending===request)document.querySelector('#recall-status').textContent='Vorgang nicht bestätigt. Mit identischem Inhalt und Schlüssel erneut senden.';}finally{if(user?.id===owner)recallLock();}}
